<template><q-page><div class="page-wrap"><PageHeader :title="title" :subtitle="subtitle" :eyebrow="mode==='profile'?'Your issued account':'SAFERSEAS workspace'"/>
<template v-if="mode==='profile'"><div class="content-grid"><section class="panel"><h3>Account details</h3><q-form @submit="saveProfile" class="form-grid"><q-input v-model="profile.name" outlined label="Full name" :rules="[v=>!!v||'Name is required']"/><q-input :model-value="user?.email" outlined label="Issued email" readonly/><q-input :model-value="roleName" outlined label="Assigned role" readonly/><q-input :model-value="user?.officeId" outlined label="Assigned office" readonly/><q-input v-model="profile.organization" outlined label="Organization" class="span-2"/><div class="span-2"><q-btn color="primary" unelevated no-caps label="Save profile" type="submit"/></div></q-form></section><section><div class="panel"><h3>Security & access</h3><p class="muted">Role and office access are assigned by a MARINA account administrator.</p><StatusBadge :status="user?.status"/><p class="text-caption q-mt-md">Scope: {{user?.scope}} · Session is local to this demonstration.</p><q-btn outline color="primary" no-caps label="Preview password change" @click="passwordDialog=true"/></div><div class="panel"><h3>Appearance</h3><q-toggle :model-value="$q.dark.isActive" label="Dark appearance" @update:model-value="theme"/></div></section></div></template>
<template v-else-if="mode==='notifications'"><section class="panel"><div class="toolbar-row"><q-toggle v-model="unreadOnly" label="Unread only"/><q-space/><q-btn flat color="primary" label="Mark all read" @click="markAll"/></div><q-list separator v-if="notices.length"><q-item v-for="n in notices" :key="n.id" class="q-py-md"><q-item-section avatar><q-icon :name="n.read?'notifications_none':'notifications_active'" :color="n.read?'grey':'primary'"/></q-item-section><q-item-section><q-item-label class="text-weight-bold">{{n.title}}</q-item-label><q-item-label caption>{{n.message}}</q-item-label><q-item-label caption>{{formatDate(n.at)}}</q-item-label></q-item-section><q-item-section side><q-btn flat no-caps color="primary" label="Open" @click="openNotice(n)"/></q-item-section></q-item></q-list><EmptyState v-else title="You’re up to date" message="New review, correction and assignment messages appear here."/></section></template>
<template v-else-if="mode==='help'"><div class="content-grid"><section class="panel"><h3>From notification to a complete case</h3><q-list separator><q-expansion-item v-for="(g,i) in guides" :key="g.title" :label="`${i+1}. ${g.title}`" :default-opened="i===0" header-class="text-weight-bold"><div class="q-pa-md muted">{{g.text}}</div></q-expansion-item></q-list></section><aside><div class="panel"><h3>Account assistance</h3><p class="muted">Your MARINA account administrator issues access and assigns permissions. This demo does not send support requests or emails.</p><q-btn outline no-caps color="primary" label="View my account" to="/profile"/></div><div class="panel"><h3>Demonstration guide</h3><p class="muted">Use the handoff to inspect screen coverage, proposed APIs and complete review journeys.</p><q-btn flat no-caps color="primary" label="Open developer handoff" to="/handoff" icon-right="arrow_forward"/></div></aside></div></template>
<template v-else><section class="panel"><EmptyState icon="lock" title="This record is unavailable" message="Your account may not have permission, or the requested record does not exist."><q-btn color="primary" no-caps unelevated label="Return to my workspace" :to="user?.role==='reporter'?'/reporter':'/admin'"/></EmptyState></section></template>
</div><q-dialog v-model="passwordDialog"><q-card><q-card-section><h3>Password change preview</h3><p class="muted">The demonstration uses the fixed password Demo2026!. Production password validation, recovery and session revocation must be implemented on the server.</p><q-input outlined label="Current password" type="password" class="q-mb-md"/><q-input outlined label="New password" type="password"/></q-card-section><q-card-actions align="right"><q-btn flat label="Close" v-close-popup/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>import{computed,ref,reactive}from'vue';import{useRoute,useRouter}from'vue-router';import{useQuasar}from'quasar';import{useDemo}from'../stores/demo.js';import PageHeader from'../components/PageHeader.vue';import StatusBadge from'../components/StatusBadge.vue';import EmptyState from'../components/EmptyState.vue';const store=useDemo(),route=useRoute(),router=useRouter(),$q=useQuasar(),user=computed(()=>store.currentUser.value),mode=computed(()=>route.meta.mode),title=computed(()=>({profile:'My account',notifications:'Inbox & notifications',help:'Help & workflow guide'}[mode.value]||'Access restricted')),subtitle=computed(()=>({profile:'Your identity, assigned access and workspace preferences.',notifications:'Follow review requests, assignments and reporting activity.',help:'Reporting and investigation guidance for issued accounts.'}[mode.value]||'Account and record permissions apply throughout the platform.')),profile=reactive({name:user.value?.name||'',organization:user.value?.organization||''}),roleName=computed(()=>store.state.roles.find(r=>r.id===user.value?.role)?.name),passwordDialog=ref(false),unreadOnly=ref(false),notices=computed(()=>store.state.notifications.filter(n=>n.userId===user.value?.id&&(!unreadOnly.value||!n.read)));const formatDate=v=>new Date(v).toLocaleString('en-PH',{timeZone:'Asia/Manila'});function saveProfile(){const u=store.state.users.find(u=>u.id===user.value.id);Object.assign(u,profile);store.audit('Updated own profile',u.id,'Name and organization only.');store.persist();$q.notify({type:'positive',message:'Profile saved in this demonstration.'})}function theme(v){$q.dark.set(v);store.state.settings.appearance=v?'dark':'light'}function markAll(){notices.value.forEach(n=>n.read=true);store.persist()}function openNotice(n){n.read=true;router.push(n.link||'/notifications')}
const guides=[{title:'Start with a spot report',text:'Enter the nature, occurrence date or explicit unknown, place description, vessels and source. Save a draft until ready. Exact coordinates and final findings are not prerequisites.'},{title:'Keep one event with every involved vessel',text:'A collision is one event with multiple vessel involvements. Preserve each vessel’s identifiers, operator, service and incident-time particulars.'},{title:'Represent unknowns honestly',text:'Blank person counts mean unknown. Enter zero only when confirmed. Date-only records and approximate locations carry explicit precision.'},{title:'Respond to corrections',text:'Open the correction request in your inbox or report timeline. Edit permitted fields, retain previous evidence and resubmit for attributed review.'},{title:'Build investigation reports in stages',text:'Staff prepare MAIC 1B, repeatable Form2 progress updates and Form3B final reports. Issued revisions remain in history; cumulative casualty observations are not added again.'},{title:'Keep office and case roles separate',text:'AOR, vessel homeport, CPC office and actual SCO-issuing office are distinct. Investigation validation does not automatically close an enforcement case.'},{title:'Generate reproducible outputs',text:'Use a saved selection, counting unit and as-of date for tables, maps and figures. CSV, XLSX and GeoJSON are local downloads; PDF uses a printable preview. Official templates remain subject to MARINA approval.'}];</script>
